  'src.pol.ratp': { en: `RATP: financial report 2025`, nl: `RATP: financieel verslag 2025`, fr: `RATP : rapport financier 2025` },
  bracketTop: { en: `45% bracket`, nl: `schijf van 45%`, fr: `tranche à 45%` },
  chartTitle: { en: `Tax and buying power at each salary level`, nl: `Belasting en koopkracht per loonniveau`, fr: `Prélèvements et pouvoir d'achat à chaque niveau de salaire` },
  chartAria: { en: `Tax rate per salary chart`, nl: `Grafiek van het belastingtarief per loon`, fr: `Graphique du taux de prélèvement par salaire` },
  trapTitle: { en: (a, b) => `Why so high between ${a} and ${b}?`, nl: (a, b) => `Waarom zo hoog tussen ${a} en ${b}?`, fr: (a, b) => `Pourquoi si élevé entre ${a} et ${b} ?` },
  trapBody: {
    en: (a, b, pa, cliff) => `Two low-wage discounts shrink as your pay rises. Your employer's general reduction (RGDU) cuts up to 40% of the salary in contributions at the SMIC and fades out up to 3 SMIC, so each extra euro also costs your employer part of that discount.${pa ? ` The prime d'activité loses about 40 cents per extra net euro once the forfait is covered, and stops at ${pa}.` : ''} At ${b} the RGDU's last 2% drops all at once: one more euro of gross costs your employer about ${cliff} a year. Above, rates fall back to the plain contribution and tax rates.`,
    nl: (a, b, pa, cliff) => `Twee kortingen voor lage lonen krimpen naarmate je loon stijgt. De algemene vermindering (RGDU) van je werkgever schrapt op het SMIC tot 40% van het loon aan bijdragen en loopt af tot 3 keer het SMIC, dus elke extra euro kost je werkgever ook een deel van die korting.${pa ? ` De prime d'activité verliest ongeveer 40 cent per extra netto euro zodra het forfait gedekt is, en stopt bij ${pa}.` : ''} Bij ${b} valt de laatste 2% van de RGDU in één keer weg: één euro bruto meer kost je werkgever dan ongeveer ${cliff} per jaar. Daarboven zakken de tarieven terug naar de gewone bijdragen en belastingen.`,
    fr: (a, b, pa, cliff) => `Deux aides aux bas salaires diminuent quand votre salaire augmente. La réduction générale (RGDU) de votre employeur efface jusqu'à 40% du salaire en cotisations au SMIC et s'éteint à 3 SMIC : chaque euro supplémentaire fait aussi perdre une partie de cette réduction.${pa ? ` La prime d'activité perd environ 40 centimes par euro net supplémentaire une fois le forfait couvert, et s'arrête à ${pa}.` : ''} À ${b}, les derniers 2% de la RGDU disparaissent d'un coup : un euro brut de plus coûte alors environ ${cliff} par an à votre employeur. Au-delà, les taux reviennent aux cotisations et impôts ordinaires.`,
  },
  topTitle: {
    en: (top, cehr) => `Why the step at ${top}${cehr ? ` and again at ${cehr}` : ''}?`,
    nl: (top, cehr) => `Waarom de sprong bij ${top}${cehr ? ` en opnieuw bij ${cehr}` : ''}?`,
    fr: (top, cehr) => `Pourquoi la marche à ${top}${cehr ? ` et encore à ${cehr}` : ''} ?`,
  },
  topBody: {
    en: (top, cehr, br, parts) => `From ${top} your household's taxable income per part (${parts} parts) passes ${br}, so the top 45% bracket starts.${cehr ? ` At ${cehr} the exceptional contribution on high incomes (CEHR) adds 3%, then 4% further up.` : ''}`,
    nl: (top, cehr, br, parts) => `Vanaf ${top} komt het belastbaar inkomen per deel van je gezin (${parts} delen) boven ${br}: de hoogste schijf van 45% begint.${cehr ? ` Bij ${cehr} komt de uitzonderlijke bijdrage op hoge inkomens (CEHR) er met 3% bij, verderop 4%.` : ''}`,
    fr: (top, cehr, br, parts) => `À partir de ${top}, le revenu imposable de votre foyer par part (${parts} parts) dépasse ${br} : la tranche à 45% commence.${cehr ? ` À ${cehr}, la contribution exceptionnelle sur les hauts revenus (CEHR) ajoute 3%, puis 4% plus haut.` : ''}`,
  },

